// 追加语言:es fr de pt ru it tr vi id(顺序与 langCodes[5:] 一致)。
// 缺失的键(如 kt.* 简写、src.*、about)自动回退英文。

func kv(p ...string) map[string]string {
	m := make(map[string]string, len(p)/2)
	for i := 0; i+1 < len(p); i += 2 {
		m[p[i]] = p[i+1]
	}
	return m
}

